from lib import folds
from scipy.special import erf
def gelu(a): return 0.5*a*(1+erf(a/np.sqrt(2)))
d=np.load('base_feats.npz'); y=d['y']
F=lnr(5*d['mean_hidden_L9']+d['cls_hidden_L9'])
def cv_gelu(F, y, g, b, lam, seeds=(0,1,2), kind='gelu'):
    accs=[]
    for s in seeds:
        P=np.zeros((len(y),8))
        for te in folds(len(y),5,s,y):
            tr=np.setdiff1d(np.arange(len(y)),te)
            Ztr,Zte=zs(F[tr],F[te]); dd=F.shape[1]
            if kind=='gelu':
                Htr=gelu(g*Ztr@Ztr.T/dd+b); Hte=gelu(g*Zte@Ztr.T/dd+b)
            else:
                Htr=rbf(Ztr,Ztr,g); Hte=rbf(Zte,Ztr,g)
            T=np.eye(8)[y[tr]]; T=T-T.mean(0)
            if kind=='gelu':
                mu=Htr.mean(0); Hc=Htr-mu
                Wt=np.linalg.solve(Hc.T@Hc+lam*np.eye(Hc.shape[1]), Hc.T@T)
                P[te]=(Hte-mu)@Wt
            else:
                al=np.linalg.solve(Htr+lam*np.eye(len(tr)),T); P[te]=Hte@al
        accs.append((P.argmax(1)==y).mean())
    return np.mean(accs)
